"""Rhythm challenge items (all music composed for this corpus and dedicated CC0 1.0;
texts public domain).  Each item: make() -> (score, layout, opts), expected-result
metadata, edge-case tags and three damage variants (scan, scan-mild, scan-severe)."""
from __future__ import annotations

from .model import set_verses
from .rdsl import build_score

CC0 = ('Music composed for the OMR rhythm challenge corpus; engraving (LilyPond 2.24), truth MusicXML, '
       'rasterisation and simulated scan damage generated by corpus/challenge/rhythm/_tools. '
       'All of it is dedicated to the public domain under CC0 1.0 '
       '(https://creativecommons.org/publicdomain/zero/1.0/).')
LIC_CC0 = 'CC0-1.0 (composition, engraving, truth and scans created for this corpus)'
COMPOSER = 'OMR challenge corpus (CC0)'


def single_layout(pid, name, short=None, clef='treble', verses=(), vkey='1'):
    st = {'id': f'st{pid}', 'clef': clef, 'name': name, 'voices': [(pid, vkey)], 'lyrics': []}
    if short:
        st['short'] = short
    if verses:
        st['lyrics'] = [{'voice': (pid, vkey), 'verses': list(verses), 'place': 'below'}]
    return {'type': None, 'staves': [st]}


def piano_group(pid, name, rh=('1',), lh=('5',), short=None):
    g = {'type': 'PianoStaff', 'name': name,
         'staves': [{'id': f'st{pid}s1', 'clef': 'treble', 'voices': [(pid, k) for k in rh], 'lyrics': []},
                    {'id': f'st{pid}s2', 'clef': 'bass', 'voices': [(pid, k) for k in lh], 'lyrics': []}]}
    if short:
        g['short'] = short
    return g


def opts_for(title, subtitle=None, composer=COMPOSER, poet=None, staff_size=20, extra_paper=(), extra_layout=()):
    hdr = {'title': title, 'composer': composer}
    if subtitle:
        hdr['subtitle'] = subtitle
    if poet:
        hdr['poet'] = poet
    return {'header': hdr, 'staff_size': staff_size, 'paper': 'a4',
            'paper_extra': list(extra_paper), 'layout_extra': list(extra_layout)}


