    sc = build_score(spec)
    lay = {'groups': [piano_group('P1', 'Piano', rh=('1', '2'), lh=('5',))]}
    return sc, lay, opts_for('Toccatina', 'for piano', staff_size=22,
                             extra_paper=['system-system-spacing.basic-distance = #24'])
